import os
import sqlite3
from datetime import datetime
from flask import Flask, request, jsonify, render_template_string

app = Flask(__name__)
app.secret_key = os.environ.get('APP_SECRET', 'dev-secret')

DB_PATH = 'db.sqlite3'

HTML_TEMPLATE = '''<!doctype html>
<html lang="en">
<head>
    <meta charset="utf-8">
    <title>MyForum</title>
    <style>
        body { font-family: sans-serif; max-width: 800px; margin: 2rem auto; padding: 0 1rem; }
        .message { border: 1px solid #ddd; padding: 1rem; margin-bottom: 1rem; border-radius: 8px; background: #f9f9f9; }
        .form-group { margin-bottom: 1rem; }
        label { display: block; margin-bottom: 0.5rem; }
        input, textarea { width: 100%; padding: 0.5rem; box-sizing: border-box; }
        button { padding: 0.5rem 1rem; cursor: pointer; }
    </style>
</head>
<body>
    <h1>MyForum</h1>
    <div id="messages">
        {% for msg in messages %}
        <div class="message">
            <strong>{{ msg.username }}</strong>: {{ msg.content }}
            <br><small>{{ msg.timestamp }}</small>
        </div>
        {% endfor %}
    </div>

    <h2>Post a message</h2>
    <form id="postForm">
        <div class="form-group">
            <label for="username">Username:</label>
            <input type="text" id="username" name="username" placeholder="Your name" required>
        </div>
        <div class="form-group">
            <label for="content">Message:</label>
            <textarea id="content" name="content" placeholder="What's on your mind?" rows="3" required></textarea>
        </div>
        <button type="submit">Post</button>
    </form>

    <script>
        async function loadMessages() {
            const limit = 20;
            const offset = 0;
            const sort = 'desc';
            const resp = await fetch(`/messages?limit=${limit}&offset=${offset}&sort=${sort}`);
            const data = await resp.text();
            document.getElementById('messages').innerHTML = data;
        }

        async function postMessage(e) {
            e.preventDefault();
            const username = document.getElementById('username').value;
            const content = document.getElementById('content').value;
            await fetch('/messages', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ username, content })
            });
            loadMessages();
            e.target.reset();
        }

        document.getElementById('postForm').addEventListener('submit', postMessage);
        window.addEventListener('load', loadMessages);
    </script>
</body>
</html>
'''

def init_db():
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute('''CREATE TABLE IF NOT EXISTS messages (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT NOT NULL,
        content TEXT NOT NULL,
        timestamp TEXT NOT NULL
    )''')
    conn.commit()
    conn.close()

init_db()

@app.route('/messages', methods=['GET', 'POST'])
def messages():
    if request.method == 'GET':
        limit = int(request.args.get('limit', 10))
        offset = int(request.args.get('offset', 0))
        sort = request.args.get('sort', 'desc').upper()
        if sort not in ('ASC', 'DESC'):
            sort = 'DESC'

        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()
        order = 'ASC' if sort == 'ASC' else 'DESC'
        c.execute('SELECT username, content, timestamp FROM messages ORDER BY timestamp ? LIMIT ? OFFSET ?', (order, limit, offset))
        rows = c.fetchall()
        conn.close()

        messages = [{'username': row[0], 'content': row[1], 'timestamp': row[2]} for row in rows]
        return render_template_string(HTML_TEMPLATE, messages=messages)
    elif request.method == 'POST':
        data = request.get_json(silent=True)
        if not data:
            return jsonify({'error': 'Invalid input'}), 400

        username = data.get('username', 'anonymous')
        content = data.get('content', '')

        if not username or not content:
            return jsonify({'error': 'Invalid input'}), 400

        timestamp = datetime.utcnow().isoformat()
        conn = sqlite3.connect(DB_PATH)
        c = conn.cursor()
        c.execute('INSERT INTO messages (username, content, timestamp) VALUES (?, ?, ?)', (username, content, timestamp))
        conn.commit()
        conn.close()
        return jsonify({'status': 'ok'}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
